for window in wx.GetTopLevelWindows():
    try:
        if "PCB Editor" not in window.GetTitle():
            continue
    except Exception:
        continue

    print("=== searching Selection Filter ===")

    for control in iter_controls(window):
        try:
            label = control.GetLabel()
        except Exception:
            label = ""

        if "Selection Filter" in str(label):
            print(
                control.__class__.__name__,
                "label =", repr(label),
                "name =", repr(control.GetName())
            )

